import json

# Hands the packaged readiness result to the requesting system through the registered Lab tool.
# Delivery is plumbing. It decides nothing and changes nothing: every field is passed exactly as the
# Result Packager produced it. Chat runs carry no request_id, so nothing is delivered for them.
FIELDS = ("request_id", "status", "summary", "validation_status", "formal_review_required", "checked_at", "findings")


def as_obj(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        start, end = value.find("{"), value.rfind("}")
        if start != -1 and end > start:
            try:
                parsed = json.loads(value[start:end + 1])
                return parsed if isinstance(parsed, dict) else None
            except ValueError:
                return None
    return None


STATUS_AFTER = {"NEEDS_REVISION": "changes needed", "READY_FOR_FORMAL_REVIEW": "formal review",
                "INPUT_REQUIRED": "changes needed", "VALIDATION_UNAVAILABLE": "changes needed"}
# The ClickUp "Content Readiness" dropdown label for each state. Readiness is separate from the task status above.
READINESS_LABEL = {"INPUT_REQUIRED": "Input Required", "NEEDS_REVISION": "Needs Revision",
                   "VALIDATION_UNAVAILABLE": "Validation Unavailable", "READY_FOR_FORMAL_REVIEW": "Ready for Formal Review"}
READINESS_FIELD, CHECKED_FIELD = "Content Readiness", "Last Checked"
MISSING_LABEL = {"market": "Market", "audience": "Audience",
                 "draft": "The draft copy Doc (named \"<task name>: Draft Copy\" in this list)",
                 "draft_content": "The draft copy (the Doc is empty)", "as_of_date": "The check date"}


def connector(tools, name, **kwargs):
    # A tool failure comes back as a value, not an exception. None means the call did not succeed.
    reply = tools.call(name, **kwargs)
    if not isinstance(reply, dict) or reply.get("response_type") == "error":
        return None
    body = reply.get("response")
    if isinstance(body, dict) and body.get("success") is False:
        return None
    if isinstance(body, dict) and "result" in body:
        body = body["result"]
    if isinstance(body, str):
        try:
            return json.loads(body)
        except ValueError:
            return {}
    return body if body is not None else {}


def bullets(items):
    return "\n".join(f"- {i}" for i in items)


def finding_line(f):
    quote = f' ("{f.get("quote")}")' if f.get("quote") else ""
    return f"{f.get('issue')}{quote}"


# What a reader sees for each recommendation basis. AI-written rewrites never read like approved wording.
SUGGEST_HEAD = {"approved_claim": "Suggested revision (approved wording)", "required_disclaimer": "Suggested revision (required disclaimer)",
                "contextual_rewrite": "Suggested rewrite (not approved copy)"}
BASIS_LINE = {"approved_claim": "approved claim", "required_disclaimer": "required disclaimer from the approved claim", "contextual_rewrite": "reviewer suggestion, not approved copy"}


def recommendation_lines(f):
    # Compact guidance for the content owner. Nothing here edits the Doc and nothing here is approval.
    rec = f.get("recommendation")
    if not isinstance(rec, dict) or not rec.get("suggested_revision") or rec.get("recommendation_basis") not in SUGGEST_HEAD:
        return ""
    basis = rec["recommendation_basis"]
    lines = [f"{SUGGEST_HEAD[basis]}: {rec['suggested_revision']}"]
    if rec.get("reason"):
        lines.append(f"Why: {rec['reason']}")
    lines.append(f"Basis: {BASIS_LINE[basis]}" + (f", {rec['source_reference']}" if rec.get("source_reference") else ""))
    return "\n" + "\n".join(lines)


def comment_text(package):
    # Built from the packaged result only. No raw JSON, tool payloads or step names.
    state, key = package.get("status"), package.get("delivery_key")
    ref = package.get("draft_ref") or ""
    findings = package.get("findings") or []
    blocking = [finding_line(f) + recommendation_lines(f) for f in findings if f.get("severity") == "blocking"][:8]
    advisories = [finding_line(f) for f in findings if f.get("severity") == "advisory"][:5]
    parts = ["CONTENT READINESS", READINESS_LABEL[state]]
    if state == "INPUT_REQUIRED":
        names = [MISSING_LABEL.get(m, m) for m in package.get("missing") or []] or ["Required input"]
        parts += ["Missing:\n" + bullets(names), "Next step:\nAdd the missing context and move the brief back into Internal Review."]
    elif state == "NEEDS_REVISION":
        parts.append("Blocking findings:\n" + ("\n\n".join(f"Finding {n}: {t}" for n, t in enumerate(blocking, 1)) if blocking else "- See the readiness report."))
        if advisories:
            parts.append("Advisories:\n" + bullets(advisories))
        parts.append("Next step:\nUpdate the draft and move the task to Internal Review when ready to check again. Suggestions are guidance, not approval.")
    elif state == "VALIDATION_UNAVAILABLE":
        parts += ["The governed validation step could not complete.", "Next step:\nRetry the readiness check or escalate the integration issue."]
    else:
        parts.append("Automated readiness is complete.")
        if advisories:
            parts.append("Advisories:\n" + bullets(advisories))
        # No Medical, Legal and Regulatory reviewer is modeled in this ClickUp workspace, so the comment asks for one rather than naming a person.
        parts += ["Human approval is still required.", "Next step:\nSend the content to formal Medical, Legal and Regulatory review. Assign this task to the appropriate Medical, Legal and Regulatory reviewer."]
    parts.append(f"Readiness ref: {key}\nDraft ref: {ref or 'none (no draft was read)'}")
    return "\n\n".join(parts)


def checked_stamp(package):
    # The packaged result already carries the completed-result time (UTC). No second clock is read.
    value = package.get("checked_at")
    return f"{value[:10]} {value[11:16]}" if isinstance(value, str) and len(value) >= 16 else None


def write_fields(tools, task_id, task, package):
    # Cosmetic metadata. A failure here is reported, never raised, and never changes the readiness result or the comment.
    fields = {f.get("name"): f for f in task.get("custom_fields") or [] if isinstance(f, dict)}
    wanted, label = [], READINESS_LABEL[package["status"]]
    ready_field = fields.get(READINESS_FIELD)
    option = next((o for o in (ready_field or {}).get("type_config", {}).get("options") or [] if o.get("name") == label), None)
    if ready_field and option and ready_field.get("id") and option.get("id"):
        wanted.append({"id": ready_field["id"], "value": option["id"]})
    stamp, checked_field = checked_stamp(package), fields.get(CHECKED_FIELD)
    if checked_field and checked_field.get("id") and stamp:
        wanted.append({"id": checked_field["id"], "value": stamp})
    if len(wanted) < 2:
        return "skipped: field or option not found"
    return "written" if connector(tools, "clickup_update_task", task_id=task_id, custom_fields=wanted) is not None else "failed"


def deliver_clickup(package):
    task_id, key = package["task_id"], package["delivery_key"]
    if package.get("duplicate"):
        return {"delivery": "skipped", "reason": "this readiness event was already delivered", "summary": f"Duplicate for task {task_id}: nothing posted."}
    target = STATUS_AFTER.get(package.get("status"))
    if target is None or package.get("status") not in READINESS_LABEL:
        raise RuntimeError("Delivery failed: the readiness state is not one this step can deliver.")
    from opal_tms_sdk import tools, OpalTmsSdkError

    try:
        task = connector(tools, "clickup_get_task", task_id=task_id, include=["custom_fields"])
        if not isinstance(task, dict) or task.get("id") != task_id:
            raise RuntimeError("Delivery failed: the ClickUp task could not be read, so nothing was written.")
        comments = connector(tools, "clickup_get_task_comments", task_id=task_id)
        if comments is None:
            raise RuntimeError("Delivery failed: existing comments could not be read, so nothing was written.")
        posted = key in json.dumps(comments)
        # Order: readiness fields, comment, then task status. The fields come first because they are repeatable and harmless.
        # The status comes last so a task is never moved on before its comment exists. A fields failure does not stop the rest.
        fields = write_fields(tools, task_id, task, package)
        if not posted:
            text = comment_text(package)
            # notify_all makes ClickUp notify the task's own assignees, so the next person hears about it through the existing
            # assignee mechanism. No person is named or hardcoded. If the connector refuses the option, post without it.
            made = connector(tools, "clickup_create_comment", entity_id=task_id, entity_type="task", comment_text=text, notify_all=True)
            if made is None:
                made = connector(tools, "clickup_create_comment", entity_id=task_id, entity_type="task", comment_text=text)
            if made is None:
                raise RuntimeError("Delivery failed: ClickUp did not accept the comment.")
        # Setting a status is repeatable, so a retry after a half-finished delivery finishes the job without a second comment.
        moved = connector(tools, "clickup_update_task", task_id=task_id, status=target)
        if moved is None:
            raise RuntimeError("Delivery failed: ClickUp did not accept the status change.")
    except OpalTmsSdkError as error:
        raise RuntimeError(f"Delivery failed: {type(error).__name__}.") from None
    return {"delivery": "delivered", "target": "clickup", "task_id": task_id, "status": package.get("status"), "task_status": target,
            "readiness_fields": fields, "comment": "already present" if posted else "posted",
            "notified": "task assignees" if task.get("assignees") else "nobody: the task has no assignee",
            "summary": f"Delivered {package.get('status')} to ClickUp task {task_id} (fields {fields.split(':')[0]})."}


def handler(input, ctx):
    package = as_obj(input.get("packager_output"))
    if package is None:
        raise RuntimeError("Delivery failed: the Result Packager output could not be read, so nothing was delivered.")
    if package.get("source") == "clickup":
        return deliver_clickup(package)
    if package.get("callback") == "invalid":
        raise RuntimeError("Delivery failed: a request_id was supplied but is not a valid identifier, so the result was not delivered.")
    if package.get("callback") != "required":
        return {"delivery": "skipped", "reason": "no request_id supplied", "summary": "Delivery skipped: no request_id, as in Chat."}

    from opal_tms_sdk import tools, OpalTmsSdkError

    try:
        reply = tools.call("submit_readiness_result", **{k: package.get(k) for k in FIELDS})
    except OpalTmsSdkError as error:
        # Opal retries a failed step. The Lab accepts an identical resubmission, so a retry is safe.
        raise RuntimeError(f"Delivery failed: {type(error).__name__}.") from None

    # A tool failure comes back as a value, not an exception, so success is checked explicitly.
    body = reply.get("response") if isinstance(reply, dict) else None
    if not (isinstance(reply, dict) and reply.get("response_type") != "error" and isinstance(body, dict) and body.get("status") == "ok"):
        code = body.get("status_code") if isinstance(body, dict) else None
        raise RuntimeError(f"Delivery failed: the Lab did not accept the result (status {code}).")
    return {"delivery": "delivered", "request_id": package["request_id"], "status": package.get("status"),
            "summary": f"Delivered {package.get('status')} for request {package['request_id']}."}

import json
from datetime import datetime, timezone

DISCLAIMER = "This is a readiness check before formal review. It is not regulatory approval."
BASES = ("approved_claim", "required_disclaimer", "contextual_rewrite")
BASIS_LABEL = {"approved_claim": "Approved wording", "required_disclaimer": "Required disclaimer", "contextual_rewrite": "Suggested rewrite (not approved copy)"}


def as_obj(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        start, end = value.find("{"), value.rfind("}")
        if start != -1 and end > start:
            try:
                parsed = json.loads(value[start:end + 1])
                return parsed if isinstance(parsed, dict) else None
            except ValueError:
                return None
    return None


def clip(value, n):
    return str(value or "")[:n]


# A recommendation is advisory text for the content owner. It is never approval and never a state. It exists only when
# something supports it: exact governed wording or a governed disclaimer from the validator, or a contextual rewrite the
# reviewer proposed. Unapproved or uncited claims get no suggested wording, because nothing governed can replace them.
def recommendation(basis, original, revised, reason, source=""):
    revised = clip(revised, 700).strip()
    if basis not in BASES or not revised:
        return None
    rec = {"suggested_revision": revised, "reason": clip(reason, 400) or "See the finding.", "recommendation_basis": basis, "human_review_required": True}
    if clip(original, 500).strip():
        rec["original_text"] = clip(original, 500)
    if clip(source, 80).strip():
        rec["source_reference"] = clip(source, 80)
    return rec


def reviewer_recommendation(f, disclaimers):
    # Disclaimer wording is governed text: only the validator's exact disclaimer may be recommended, never a model's version.
    if f.get("type") == "disclaimer":
        texts = sorted({d.get("required_disclaimer") for d in disclaimers if isinstance(d, dict) and isinstance(d.get("required_disclaimer"), str)})
        if len(texts) != 1:
            return None
        ids = ", ".join(sorted({d.get("claim_id") for d in disclaimers if d.get("required_disclaimer") == texts[0] and d.get("claim_id")}))
        return recommendation("required_disclaimer", "", texts[0], f.get("issue"), ids)
    revised = f.get("suggested_revision")
    if isinstance(revised, str) and revised.strip():
        return recommendation("contextual_rewrite", f.get("quote"), revised, f.get("issue"))
    return None


def rec_lines(rec):
    if not isinstance(rec, dict) or not rec.get("suggested_revision"):
        return []
    label = BASIS_LABEL.get(rec.get("recommendation_basis"), "Suggestion")
    out = [f"  - Suggested revision ({label}): \"{rec['suggested_revision']}\"", f"  - Why: {rec.get('reason')}"]
    if rec.get("source_reference"):
        out.append(f"  - Source: {rec['source_reference']}")
    return out


def report(state, reason, context, claims, unresolved, findings):
    lines = [f"# Readiness: {state}", "", reason, "", context, ""]
    if claims:
        lines.append("## Claims")
        for c in claims:
            why = ", ".join(c.get("reasons") or []) or c.get("tool_outcome", "")
            lines.append(f"- {c.get('claim_id')}: {c.get('explanation')} ({why})")
            if c.get("wording_matches") is False and c.get("approved_text"):
                lines.append(f"  - Draft: \"{c.get('draft_text')}\"")
                lines.append(f"  - Approved: \"{c.get('approved_text')}\"")
            lines += rec_lines(c.get("recommendation"))
        lines.append("")
    if unresolved:
        lines.append("## Claim statements with no claim ID")
        lines += [f"- \"{u.get('draft_text')}\". {u.get('explanation')}" for u in unresolved]
        lines.append("")
    if findings:
        lines.append("## Content findings")
        for f in findings:
            tag = "Blocking" if f.get("blocking") else "Advisory"
            lines.append(f"- {tag}, {f.get('type')}: \"{f.get('quote')}\". {f.get('issue')} {f.get('suggestion')}")
            lines += rec_lines(f.get("recommendation"))
        lines.append("")
    lines.append(DISCLAIMER)
    return "\n".join(lines)


def finish(state, reason, ctx, inp, claims=(), unresolved=(), findings=(), blocking=(), disclaimers=()):
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    context = f"Market: {inp.get('market') or 'not given'}. Audience: {inp.get('audience') or 'not given'}. Claims checked as of: {inp.get('as_of_date') or 'run date'}. Generated: {stamp}."
    md = report(state, reason, context, list(claims), list(unresolved), list(findings))
    try:
        with open(f"{ctx['output_dir']}/readiness-report.md", "w") as fh:
            fh.write(md)
    except Exception:
        pass  # the file is a convenience; the state is the result
    return {"state": state, "reason": reason, "claim_issues": list(claims), "unresolved_candidate_claims": list(unresolved),
            "blocking_findings": list(blocking), "findings": list(findings), "governed_disclaimers": list(disclaimers),
            "report_markdown": md, "summary": f"{state}: {reason}"}


def handler(input, ctx):
    if input.get("gate") != "INPUTS_OK":
        return finish("INPUT_REQUIRED", "The draft, market or audience was missing or malformed. Nothing was checked.", ctx, input)

    claims = as_obj(input.get("claims_output"))
    if claims is None:
        return finish("VALIDATION_UNAVAILABLE", "The claim check result could not be read. Do not send the draft to formal review on this result.", ctx, input)
    cited = [i for i in (input.get("cited_claim_ids") or "").split(",") if i]
    status = claims.get("validation_status")
    returned = [c.get("claim_id") for c in claims.get("claims", [])]
    if cited and status != "ok":
        return finish("VALIDATION_UNAVAILABLE", f"Claim validation did not complete (status: {status}). Run the check again later.", ctx, input)
    if not cited and status != "not_called":
        return finish("VALIDATION_UNAVAILABLE", f"Unexpected validation status with no cited IDs (status: {status}).", ctx, input)
    if sorted(set(returned)) != sorted(set(cited)):
        return finish("VALIDATION_UNAVAILABLE", "The claim results do not match the cited claim IDs, so they cannot be trusted.", ctx, input)

    review = as_obj(input.get("review_output"))
    if review is None:
        return finish("VALIDATION_UNAVAILABLE", "The content review result could not be read. Run the check again.", ctx, input)

    findings = review.get("findings", [])
    blocking = [f for f in findings if f.get("blocking")]
    if review.get("blocking_findings") is True and not blocking:
        blocking = [{"type": "unspecified", "quote": "", "issue": "The reviewer flagged a blocking issue without detail.", "suggestion": "Run the check again.", "blocking": True}]
        findings = findings + blocking
    claim_issues = [c for c in claims.get("claims", []) if c.get("tool_outcome") != "valid" or c.get("wording_matches") is not True]
    unresolved = claims.get("unresolved_candidate_claims", [])
    validated = (not cited) or claims.get("all_valid") is True

    if validated and not claim_issues and not unresolved and not blocking:
        return finish("READY_FOR_FORMAL_REVIEW", "Every cited claim is valid with matching wording, there is no uncited claim and no blocking content finding.", ctx, input,
                      claims=claims.get("claims", []), findings=findings)
    # Exact governed disclaimers from the validator, for the claims it returned. Quoted unchanged, never rewritten.
    disclaimers = [{"claim_id": c.get("claim_id"), "required_disclaimer": c.get("required_disclaimer")}
                   for c in claims.get("claims", []) if isinstance(c.get("required_disclaimer"), str) and c.get("required_disclaimer").strip()]
    # Recommendations ride only on blocking findings of a NEEDS_REVISION result. Exact approved wording comes from the validator.
    claim_issues = [{**c, "recommendation": rec} if (rec := recommendation("approved_claim", c.get("draft_text"), c.get("approved_text"), c.get("explanation"), c.get("claim_id"))
                                                        if c.get("tool_outcome") == "valid" and c.get("wording_matches") is False else None) else c for c in claim_issues]
    findings = [{**f, "recommendation": rec} if f.get("blocking") and (rec := reviewer_recommendation(f, disclaimers)) else f for f in findings]
    blocking = [f for f in findings if f.get("blocking")]
    return finish("NEEDS_REVISION", "Fix the items below and run the check again.", ctx, input,
                  claims=claim_issues, unresolved=unresolved, findings=findings, blocking=blocking, disclaimers=disclaimers)

import json
import re
from datetime import datetime, timezone

# Turns the Readiness Decision output into the CMS-facing result and says whether a callback is needed.
# It decides nothing: the state comes from the Readiness Decision step, unchanged. It only reshapes.
UUID = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$")
STATES = ("INPUT_REQUIRED", "NEEDS_REVISION", "READY_FOR_FORMAL_REVIEW", "VALIDATION_UNAVAILABLE")


def as_obj(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        start, end = value.find("{"), value.rfind("}")
        if start != -1 and end > start:
            try:
                parsed = json.loads(value[start:end + 1])
                return parsed if isinstance(parsed, dict) else None
            except ValueError:
                return None
    return None


def clip(value, n):
    return str(value or "")[:n]


def finding(kind, severity, quote, issue, suggestion, recommendation=None):
    out = {"type": clip(kind, 40) or "other", "severity": severity, "quote": clip(quote, 500),
           "issue": clip(issue, 700) or "See the readiness report.", "suggestion": clip(suggestion, 700)}
    if recommendation:
        out["recommendation"] = recommendation
    return out


# RC3 builds recommendations once, from governed validator data or the reviewer's contextual suggestion. RC4 only carries
# a well formed one through to the external result and drops anything else, so a malformed or misplaced one never ships.
BASES = ("approved_claim", "required_disclaimer", "contextual_rewrite")


def carried(rec):
    if not isinstance(rec, dict) or rec.get("recommendation_basis") not in BASES:
        return None
    revised = clip(rec.get("suggested_revision"), 700).strip()
    source = clip(rec.get("source_reference"), 80).strip()
    # Governed wording must name its source. Without one it cannot be called governed.
    if not revised or (rec["recommendation_basis"] != "contextual_rewrite" and not source):
        return None
    out = {"suggested_revision": revised, "reason": clip(rec.get("reason"), 400) or "See the finding.",
           "recommendation_basis": rec["recommendation_basis"], "human_review_required": True}
    if clip(rec.get("original_text"), 500).strip():
        out["original_text"] = clip(rec.get("original_text"), 500)
    if source:
        out["source_reference"] = source
    return out


def read_request_id(value):
    # The id is never corrected. Empty means no external caller (Chat). An exact UUID is delivered.
    # Anything else was meant as an id but cannot be trusted, so delivery fails instead of silently skipping.
    if isinstance(value, list):
        if len(value) > 1:
            return "", "invalid"
        value = value[0] if value else ""
    if value is None or (isinstance(value, str) and value == ""):
        return "", "not_required"
    if isinstance(value, str) and UUID.fullmatch(value):
        return value, "required"
    return "", "invalid"


TASK_ID = re.compile(r"[A-Za-z0-9]{4,20}")
KEY = re.compile(r"[0-9a-f]{16}")


def read_intake(value):
    # The intake step says where the request came from. A ClickUp source must carry a well-formed task and delivery key,
    # or delivery would act on an identifier nobody can trust, so the run fails instead.
    intake = as_obj(value) or {}
    if intake.get("source") != "clickup":
        return {"source": "direct"}
    task_id, key = intake.get("task_id"), intake.get("delivery_key")
    missing = intake.get("missing") if isinstance(intake.get("missing"), list) else []
    if not (isinstance(task_id, str) and TASK_ID.fullmatch(task_id)):
        raise RuntimeError("Packaging failed: the ClickUp task id is not valid.")
    if not (isinstance(key, str) and KEY.fullmatch(key)):
        raise RuntimeError("Packaging failed: the ClickUp delivery key is not valid.")
    # The draft ref is the first 8 characters of the draft's SHA-256 from IN1. It tells a reader which text was checked.
    # Empty when there was no draft to hash. Never the full hash.
    sha = intake.get("draft_sha256")
    draft_ref = sha[:8] if isinstance(sha, str) and re.fullmatch(r"[0-9a-f]{64}", sha) else ""
    return {"source": "clickup", "task_id": task_id, "task_name": clip(intake.get("task_name"), 200), "delivery_key": key, "draft_ref": draft_ref,
            "duplicate": intake.get("duplicate") is True, "missing": [clip(m, 40) for m in missing]}


def handler(input, ctx):
    rid, callback = read_request_id(input.get("request_id"))
    source = read_intake(input.get("intake_output"))
    decision = as_obj(input.get("decision_output"))
    state = decision.get("state") if decision else None
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

    if state not in STATES:
        # If the decision cannot be read, say so. Never guess a state, never report ready.
        return {**source, "callback": callback, "request_id": rid, "status": "VALIDATION_UNAVAILABLE",
                "summary": "The readiness decision could not be read, so nothing is reported as ready.",
                "validation_status": "validation_unavailable", "formal_review_required": True, "checked_at": now, "findings": []}

    findings = []
    if state == "NEEDS_REVISION":
        for c in decision.get("claim_issues") or []:
            wording_only = c.get("tool_outcome") == "valid"
            rec = carried(c.get("recommendation")) if wording_only else None
            findings.append(finding(
                "claim_wording" if wording_only else "claim_validity", "blocking", c.get("draft_text"), c.get("explanation"),
                "Change the wording to match the approved claim, or remove the statement." if wording_only
                else "Use an approved claim for this market and audience, or remove the statement.", rec))
        for u in decision.get("unresolved_candidate_claims") or []:
            findings.append(finding("uncited_claim", "blocking", u.get("draft_text"), u.get("explanation"),
                                    "Cite an approved claim, or rewrite it as non-claim copy."))
    for f in decision.get("findings") or []:
        # Recommendations ride only on blocking findings of a NEEDS_REVISION result.
        rec = carried(f.get("recommendation")) if state == "NEEDS_REVISION" and f.get("blocking") else None
        findings.append(finding(f.get("type"), "blocking" if f.get("blocking") else "advisory", f.get("quote"), f.get("issue"), f.get("suggestion"), rec))

    blocking = sum(1 for f in findings if f["severity"] == "blocking")
    if state == "NEEDS_REVISION":
        summary = f"{blocking} item{'s' if blocking != 1 else ''} to resolve before formal review."
    elif state == "READY_FOR_FORMAL_REVIEW":
        summary = "No blocking issues found. Ready for formal review."
    elif state == "INPUT_REQUIRED":
        summary = "The draft, market or audience was missing, so nothing was checked."
    else:
        summary = "The claims could not be checked, so the draft is not sent on."
    validation = "validation_unavailable" if state == "VALIDATION_UNAVAILABLE" else ("not_called" if state == "INPUT_REQUIRED" else "ok")

    return {**source, "callback": callback, "request_id": rid, "status": state, "summary": summary,
            "validation_status": validation, "formal_review_required": True, "checked_at": now, "findings": findings}

import hashlib
import json
import re
from datetime import date

# IN1. Checks the request before review. A ClickUp-started run arrives as the raw Call webhook body: this step parses it
# with code, reads the task and the draft Doc through the ClickUp connector, and hands on exact values. No model picks the
# task ID or rewrites the draft. Every other source (Chat, Lab) behaves as before.
TASK_ID = re.compile(r"[A-Za-z0-9]{4,20}")
DRAFT_DOC_SUFFIX = ": Draft Copy"


def as_obj(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        start, end = value.find("{"), value.rfind("}")
        if start != -1 and end > start:
            try:
                parsed = json.loads(value[start:end + 1])
                return parsed if isinstance(parsed, dict) else None
            except ValueError:
                return None
    return None


def parse_clickup(raw):
    # ClickUp's Call webhook body: {date, auto_id, payload: {id, name, status: {status}, ...}}. Anything else is not ClickUp.
    body = as_obj(raw)
    if not body or "auto_id" not in body or not isinstance(body.get("payload"), dict):
        return None
    task = body["payload"]
    status = task.get("status")
    return {"task_id": task.get("id"), "task_name": task.get("name"), "fired": str(body.get("date") or ""),
            "status": status.get("status") if isinstance(status, dict) else status}


def connector(tools, name, **kwargs):
    # A tool failure comes back as a value, not an exception. None means the call did not succeed.
    try:
        reply = tools.call(name, **kwargs)
    except Exception:
        return None
    if not isinstance(reply, dict) or reply.get("response_type") == "error":
        return None
    body = reply.get("response")
    if isinstance(body, dict) and body.get("success") is False:
        return None
    if isinstance(body, dict) and "result" in body:
        body = body["result"]
    if isinstance(body, str):
        try:
            body = json.loads(body)
        except ValueError:
            return None
    return body


def field_value(task, name):
    for f in task.get("custom_fields") or []:
        if f.get("name") != name:
            continue
        value = f.get("value")
        if f.get("type") == "drop_down":
            if isinstance(value, int) and not isinstance(value, bool):
                for o in (f.get("type_config") or {}).get("options") or []:
                    if o.get("orderindex") == value:
                        return o.get("name") or ""
            return ""
        if f.get("type") == "tasks" and isinstance(value, list):
            return ", ".join(str(v.get("name")) for v in value if isinstance(v, dict))
        return value if isinstance(value, str) else ""
    return ""


def find_draft_doc(tools, task_name, list_id):
    # The Doc is found by its name, "<task name>: Draft Copy", inside the task's own list. Exactly one match or nothing.
    wanted, matches, cursor = f"{task_name}{DRAFT_DOC_SUFFIX}", [], None
    for _ in range(3):
        args = {"keywords": wanted, "filters": {"asset_types": ["doc"]}, "count": 10}
        if cursor:
            args["cursor"] = cursor
        found = connector(tools, "clickup_search", **args)
        if not isinstance(found, dict):
            return None, "unavailable"
        for r in found.get("results") or []:
            sub = ((r.get("hierarchy") or {}).get("subcategory") or {}).get("id")
            if r.get("type") == "doc" and r.get("name") == wanted and str(sub) == str(list_id):
                matches.append(r)
        cursor = found.get("next_cursor")
        if not cursor:
            break
    if len(matches) != 1:
        return None, "not_found" if not matches else "ambiguous"
    return matches[0], "ok"


def seal(out, info, tools):
    # The delivery key ties one readiness result to one ClickUp event (task, the time the Automation fired) and one draft.
    # A retried webhook repeats the same event and draft, so it repeats the key. A new move to Internal Review does not.
    out["delivery_key"] = hashlib.sha256(f"{out['task_id']}|{info.get('fired')}|{out['draft_sha256']}".encode()).hexdigest()[:16]
    comments = connector(tools, "clickup_get_task_comments", task_id=out["task_id"])
    out["duplicate"] = comments is not None and out["delivery_key"] in json.dumps(comments)
    return out


def resolve_clickup(info, tools):
    task_id = info["task_id"]
    out = {"source": "clickup", "task_id": task_id, "missing": [], "duplicate": False, "draft_content": "", "market": "", "audience": "",
           "delivery_key": "", "draft_sha256": "", "doc_id": "", "doc_updated": "", "list_id": "", "task_name": "", "product": "", "campaign": ""}
    task = connector(tools, "clickup_get_task", task_id=task_id, include=["custom_fields"])
    if not isinstance(task, dict) or task.get("id") != task_id:
        raise RuntimeError("ClickUp task could not be read through the connector, so nothing was checked.")
    if info.get("task_name") and task.get("name") != info["task_name"]:
        raise RuntimeError("The task read through the connector does not match the webhook payload, so nothing was checked.")
    out.update(task_name=task.get("name") or "", list_id=str((task.get("list") or {}).get("id") or ""),
               market=field_value(task, "Market"), audience=field_value(task, "Audience"),
               product=field_value(task, "Product / Offering"), campaign=field_value(task, "Campaign / Initiative"))
    doc, why = find_draft_doc(tools, out["task_name"], out["list_id"])
    if why == "unavailable":
        raise RuntimeError("ClickUp Docs could not be searched through the connector, so nothing was checked.")
    if doc is None:
        out["missing"].append("draft")
        return seal(out, info, tools)
    out.update(doc_id=doc.get("id") or "", doc_updated=str(doc.get("dateUpdated") or ""))
    page = connector(tools, "clickup_get_document_pages", document_id=doc.get("id"), page_ids=[doc.get("pageId")], content_format="text/plain")
    pages = page.get("pages") if isinstance(page, dict) else None
    if not pages or not isinstance(pages[0].get("content"), str):
        raise RuntimeError("The draft Doc could not be read through the connector, so nothing was checked.")
    draft = pages[0]["content"]
    out["draft_content"] = draft
    out["draft_sha256"] = hashlib.sha256(draft.encode("utf-8")).hexdigest()
    return seal(out, info, tools)


def handler(input, ctx):
    draft = (input.get("draft_content") or "").strip()
    market = (input.get("market") or "").strip().upper()
    audience = (input.get("audience") or "").strip().lower()
    as_of = (input.get("as_of_date") or "").strip()
    resolved = {"source": "direct", "task_id": "", "delivery_key": "", "duplicate": False, "draft_content": "", "doc_id": "", "doc_updated": "",
                "draft_sha256": "", "task_name": "", "product": "", "campaign": ""}
    missing = []

    info = parse_clickup(input.get("webhook_payload"))
    if info is not None:
        if not isinstance(info["task_id"], str) or not TASK_ID.fullmatch(info["task_id"]):
            missing.append("clickup_task_id")
            resolved.update(source="clickup")
        else:
            from opal_tms_sdk import tools
            resolved = resolve_clickup(info, tools)
            missing += resolved["missing"]
            draft, market, audience = resolved["draft_content"].strip(), resolved["market"].strip().upper(), resolved["audience"].strip().lower()
    if not draft and "draft" not in missing and "clickup_task_id" not in missing:
        missing.append("draft_content")
    if not re.fullmatch(r"[A-Z]{2}", market):
        missing.append("market")
    if audience not in ("hcp", "patient"):
        missing.append("audience")
    if as_of:
        try:
            date.fromisoformat(as_of)
        except ValueError:
            missing.append("as_of_date")
    full_draft = resolved["draft_content"] if resolved["source"] == "clickup" else draft
    ids = sorted(set(re.findall(r"\[(CLM-\d{3})\]", full_draft)))
    gate = "INPUT_REQUIRED" if missing else ("DUPLICATE_DELIVERED" if resolved["duplicate"] else "INPUTS_OK")
    # Every value echoed here is pattern-checked, so the Condition's text match cannot be spoofed by draft content.
    return {
        "gate": gate,
        "missing": missing,
        "market": market if "market" not in missing else "",
        "audience": audience if "audience" not in missing else "",
        "as_of_date": as_of if "as_of_date" not in missing else "",
        "cited_claim_ids": ",".join(ids),
        "source": resolved["source"],
        "task_id": resolved["task_id"],
        "task_name": resolved["task_name"],
        "delivery_key": resolved["delivery_key"],
        "duplicate": resolved["duplicate"],
        "doc_id": resolved["doc_id"],
        "doc_updated": resolved["doc_updated"],
        "draft_sha256": resolved["draft_sha256"],
        "draft_content": full_draft if resolved["source"] == "clickup" else "",
        "summary": f"{gate}: {', '.join(missing) or 'all inputs present'}; cited IDs: {', '.join(ids) or 'none'}",
    }
